import * as T from './vendor/three.module.js';
import {generatedMap} from './generated-materials.mjs';
import {createHumanCharacter} from './human-character.mjs';
import {mergeStaticChildren} from './merge-static.mjs';
export function buildShopInterior(scene,colliders,interactive,targets,label,animated){
 const root=new T.Group();root.userData.kind='walkable-village-shop';scene.add(root);const mat=(color,e={})=>new T.MeshStandardMaterial({color,roughness:.9,...e}),wood=mat('#ffffff',{map:generatedMap('home-wood-20261018')}),cream=mat('#efe2c5'),dark=mat('#6e5037'),glass=mat('#a6c8c2',{emissive:'#ffe1a0',emissiveIntensity:.1,roughness:.2});glass.userData.nightWindow=true;
 const box=(w,h,d,m,x,y,z)=>{const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 box(10.4,.16,8.6,wood,0,-.08,0);box(10.4,3.6,.14,cream,0,1.8,-4.3);box(.14,3.6,8.6,wood,-5.2,1.8,0);box(.14,3.6,8.6,wood,5.2,1.8,0);for(const x of[-4.4,4.4])box(1.2,1.7,.12,glass,x,2,-4.15);
 const categories=[{id:'dairy',title:'Käsebedarf',x:-3.8,z:-1.8,items:['rennet','milk','salt','water','hay','grain']},{id:'chocolate',title:'Schokolade & Backen',x:3.8,z:-1.8,items:['cocoa','cocoaSeed','milk','honey','sugar','oatMilk','flour','butter']},{id:'materials',title:'Werkzeug & Material',x:-3.8,z:1,items:['wood','plank','stone','fiber','cloth','cord','nails','ingot','axe','pickaxe','lantern','tent']},{id:'food',title:'Proviant & Saisonales',x:3.8,z:1,items:['pumpkin','christmasTree','bread','berryBread','apple','nuts','veganMeal','oatMilk','autumnDecor','halloweenDecor','christmasDecor']}];
 const goods=['#dec99e','#9e5e3c','#b1b99b','#bd8b4d'].map(c=>mat(c));for(const[c,cat]of categories.entries()){for(let row=0;row<3;row++){box(1.1,.12,1.7,wood,cat.x,.55+row*.75,cat.z);for(let i=0;i<4;i++){const bottle=new T.Mesh(new T.CylinderGeometry(.09,.11,.28,10),goods[c]);bottle.position.set(cat.x+(i%2-.5)*.38,.75+row*.75,cat.z+(i<2?-.4:.4));root.add(bottle);}}colliders.push({x:cat.x,z:cat.z,w:1.2,d:1.8});const point={id:'shop-'+cat.id,name:cat.title+' ansehen',x:cat.x+(cat.x<0?1.3:-1.3),z:cat.z,range:1.6,shopCategory:cat.items};interactive.push(point);const plaque=label(cat.title,cat.x,2.65,cat.z+.9,1.9);plaque.userData.navigationId=point.id;targets.push(plaque);}
 box(4,1,.9,wood,0,.5,-2.8);box(4.2,.1,1.05,dark,0,1.04,-2.8);colliders.push({x:0,z:-2.8,w:4.2,d:1.05});const counter={id:'shop-counter',name:'Dorfladen · Einkaufen & verkaufen',x:0,z:-1.4,range:1.8,fodderShop:true};interactive.push(counter);const sign=label('Dorfladen · Grüezi!',0,2.85,-4.15,3.4);sign.userData.navigationId=counter.id;targets.push(sign);
 const clerk=createHumanCharacter('woman',{hat:false,backpack:false,jacket:'#6e8971',glasses:false,hair:'#624b37'});clerk.g.position.set(0,0,-3.65);clerk.g.userData.kind='village-shopkeeper';scene.add(clerk.g);animated.push(t=>clerk.animate({time:t,interacting:true}));mergeStaticChildren(root);return root;
}
